   430	    }
   431	  if (y0 < 0)
   432	    {
   433	      y0 = 0;
   434	    }
   435	  if (x1 >= dst_w)
   436	    {
   437	      x1 = dst_w - 1;
   438	    }
   439	  if (y1 >= dst_h)
   440	    {
   441	      y1 = dst_h - 1;
   442	    }
   443	  if (x1 < x0 || y1 < y0)
   444	    {
   445	      return true;
   446	    }
   447	
   448	  clipped = (x0 != 0 || y0 != 0 || x1 != dst_w - 1 || y1 != dst_h - 1);
   449	
   450	  /*
   451	   * 反投影出"这块目的像素会采到哪些源行"。
   452	   *
   453	   * HAL 在 EPIC_GetRotatedArea() 里把目的矩形按 `3600 - angle` 转回源坐标
   454	   * （矩阵 [cos -sin; sin cos]，`bf0_hal_epic.c:1048`，调用点 `:860-880`，最后 AABB ±1），
   455	   * 等价于 `源 = pivot + R(-θ)·(目的 − dst_c)`。这里只需要**行区间**：
   456	   * x 方向按整行 clean 就够（多清的只是同一行的别处），真正决定 cache 正确性的是
   457	   * 哪些源行会被 EPIC 读到。外扩 2 px：HAL 自己 ±1，最近邻取样也允许 1 px 偏差。
   458	   */
   459	  {
   460	    const double th = (double)angle10 * (0.1 * M_PI / 180.0);
   461	    const double c = cos(th);
   462	    const double s = sin(th);
   463	    const int32_t u[4] = { x0, x1, x0, x1 };
   464	    const int32_t v[4] = { y0, y0, y1, y1 };
   465	    int32_t i;
   466	
   467	    for (i = 0; i < 4; i++)
   468	      {
   469	        const double dx = (double)(u[i] - dst_cx);
   470	        const double dy = (double)(v[i] - dst_cy);
   471	        /*
   472	         * 两种 sinc 符号都算一遍取并集。sin 的符号取决于"画布 y 轴向下 + EPIC 旋向"
   473	         * 这套约定的组合，而它**只影响这里清多少行**（多清几行 ≈ 几十微秒），
   474	         * 不值得为它冒"清错行 ⇒ EPIC 读到陈旧像素/花屏"的风险。
   475	         */
   476	        const int32_t y_a = (int32_t)lround((double)pivot_y - s * dx + c * dy);
   477	        const int32_t y_b = (int32_t)lround((double)pivot_y + s * dx + c * dy);
   478	        const int32_t yy0 = (y_a < y_b) ? y_a : y_b;
   479	        const int32_t yy1 = (y_a < y_b) ? y_b : y_a;
   480	
   481	        if (yy0 < sy0)
   482	          {
   483	            sy0 = yy0;
   484	          }
   485	        if (yy1 > sy1)
   486	          {
   487	            sy1 = yy1;
   488	          }
   489	      }
   490	
   491	    sy0 -= 2;
   492	    sy1 += 2;
   493	    if (sy0 < 0)
   494	      {
   495	        sy0 = 0;
   496	      }
   497	    if (sy1 >= src_h)
   498	      {
   499	        sy1 = src_h - 1;
   500	      }
   501	    if (sy1 < sy0)
   502	      {
   503	        /* 反投影出了荒唐区间（NaN/溢出防御）：退回整幅，宁可多清。 */
   504	        sy0 = 0;
   505	        sy1 = src_h - 1;
   506	      }
   507	  }
   508	
   509	  /* EPIC 绕过 CPU 缓存直读 PSRAM：只把**被采样的那几行**写回去。 */
   510	  lv_epic_clean_invalidate_cache_range(
   511	    (const uint8_t *)src_buf + (size_t)sy0 * src_stride,
   512	    (size_t)(sy1 - sy0 + 1) * src_stride);
   513	
   514	  /*
   515	   * 背景 = 目的缓冲的 clip 矩形。
   516	   *
   517	   * ⚠ `data` 必须指向 (x_offset,y_offset) 对应的那个像素，**不是缓冲基址**
   518	   * （`bf0_hal_epic.h:297-300` 的层约定；HAL 用 CANVAS_TL_POS + AHB_MEM 做
   519	   * 画布→缓冲映射，见 `bf0_hal_epic.c:1910-1930`）。
   520	   * 保持 x_offset/y_offset = clip 左上角 ⇒ 画布坐标空间与整幅旋转时完全一致，
   521	   * 源层的反投影与采样相位才不变。
   522	   */
   523	  HAL_EPIC_LayerConfigInit(&layers[0]);
   524	  layers[0].data = (uint8_t *)dst_buf + (size_t)y0 * dst_stride
   525	    + (size_t)x0 * sizeof(uint16_t);
   526	  layers[0].color_mode = EPIC_COLOR_RGB565;
   527	  layers[0].width = (uint16_t)(x1 - x0 + 1);
   528	  layers[0].height = (uint16_t)(y1 - y0 + 1);
   529	  layers[0].x_offset = (int16_t)x0;
   530	  layers[0].y_offset = (int16_t)y0;
   531	  layers[0].total_width = MYVENDOR_EPIC_PX_PER_ROW(dst_stride);
   532	  /*
   533	   * 适配层 `lv_epic_flush_layers_cache()` 会按 data_size 整层扫一遍（:614-646）；
   534	   * 整幅时 468 KB > 16 KB D-cache ⇒ 每次都是一次全 cache 操作。子矩形路径的维护
   535	   * 已由上面（源行 clean）和下面（目的行 invalidate）按实际区域做完，所以把
   536	   * data_size 压到 1；**整幅路径保持原样**（data_size=0 ⇒ 整层 flush），
   537	   * 这样"整幅 = 改前行为"可以逐条对照。
   538	   * 该字段在 HAL 里只有 ezip 分支读（`bf0_hal_epic.c:3254`），RGB565 合成不受影响。
   539	   */
   540	  layers[0].data_size = clipped ? 1u : 0u;
   541	
   542	  HAL_EPIC_LayerConfigInit(&layers[1]);          /* 前景 = 源整层 + 变换 */
   543	  layers[1].data = (uint8_t *)src_buf;
   544	  layers[1].color_mode = EPIC_COLOR_RGB565;
   545	  layers[1].width = (uint16_t)src_w;
   546	  layers[1].height = (uint16_t)src_h;
   547	  layers[1].x_offset = (int16_t)(dst_cx - pivot_x);
   548	  layers[1].y_offset = (int16_t)(dst_cy - pivot_y);
   549	  layers[1].total_width = MYVENDOR_EPIC_PX_PER_ROW(src_stride);
   550	  layers[1].data_size = clipped ? 1u : 0u;      /* 同上：子矩形时源侧已按行 clean */
   551	  layers[1].transform_cfg.angle = (uint16_t)angle10;
   552	  layers[1].transform_cfg.pivot_x = (int16_t)pivot_x;
   553	  layers[1].transform_cfg.pivot_y = (int16_t)pivot_y;
   554	  layers[1].transform_cfg.scale_x = EPIC_INPUT_SCALE_NONE;
   555	  layers[1].transform_cfg.scale_y = EPIC_INPUT_SCALE_NONE;
   556	
   557	  memcpy(&out, &layers[0], sizeof(out));
   558	
   559	  /*
   560	   * 超时也算失败：HAL 的 `EPIC_WaitDone()` 超时只把 `g_epic_wait_timeouts` 加一
   561	   * 仍返回 HAL_OK（`bf0_hal_epic.c` 的等待路径），照 HAL_OK 收下会把"没转完的
   562	   * 像素"当成功，调用方随后清掉脏区/记账 ⇒ 屏上永久停在半张图。本文件其它搬运
   563	   * 路径（copy/fill）一直用 `epic_result()` 兜这件事，旋转两条路径也接上。
   564	   */
   565	  ok = epic_result(wt_before, lv_epic_blend(layers, 2, &out) == HAL_OK,
   566	    "rotate");
   567	
   568	  if (ok)
   569	    {
   570	      /* 目的侧只作废被写到的行（R 只由 EPIC 写，CPU 不会留下脏行）。 */
   571	      epic_invalidate_rect_rows(layers[0].data, dst_stride, x1 - x0 + 1,
   572	        y1 - y0 + 1);
   573	    }
   574	
   575	  return ok;
   576	}
