   600	/**
   601	 * @brief 子矩形旋转自检：整幅烘一次留底，再只用子矩形覆盖同一块，逐像素比对。
   602	 *
   603	 * @details 判两件事 —— 都只在"整幅对、子矩形错"时才会暴露：
   604	 *          ① clip 内与整幅**逐像素相同**（验 HAL 的 data/x_offset 契约与反投影相位）；
   605	 *          ② clip 外**一个像素都没被写**（验输出层裁剪语义）。
   606	 *          源/目的缓冲与 `myvendor_epic_rotate_selftest()` 共用，额外只占一个
   607	 *          20x20 快照（800 B）。背景先灌 SENTINEL 再烘：整幅路径里"没被前景覆盖"
   608	 *          的像素会保持背景色，这样两条路径的判据才一致。
   609	 */
   610	static bool epic_rotate_area_selftest(uint16_t * src, uint16_t * dst,
   611	  int32_t src_w, int32_t src_h, int32_t dst_w, int32_t dst_h, int32_t angle10,
   612	  int32_t piv)
   613	{
   614	  enum
   615	  {
   616	    CLIP_X = 14, CLIP_Y = 14, CLIP_W = 20, CLIP_H = 20, SENTINEL = 0xA5A5
   617	  };
   618	  static uint16_t snap[CLIP_W * CLIP_H];
   619	  int32_t x;
   620	  int32_t y;
   621	  int32_t bad_in = 0;
   622	  int32_t bad_out = 0;
   623	
   624	  for (y = 0; y < dst_h; y++)
   625	    {
   626	      for (x = 0; x < dst_w; x++)
   627	        {
   628	          dst[y * dst_w + x] = SENTINEL;
   629	        }
   630	    }
   631	
   632	  if (!myvendor_epic_rotate_impl(src, (uint32_t)src_w * sizeof(uint16_t),
   633	          src_w, src_h, dst, (uint32_t)dst_w * sizeof(uint16_t), dst_w, dst_h,
   634	          angle10, piv, piv, dst_w / 2, dst_h / 2, 0, 0, dst_w, dst_h))
   635	    {
   636	      syslog(LOG_WARNING, "[vrot] area selftest SKIP: full rotate failed");
   637	      return false;
   638	    }
   639	
   640	  for (y = 0; y < CLIP_H; y++)
   641	    {
   642	      for (x = 0; x < CLIP_W; x++)
   643	        {
   644	          snap[y * CLIP_W + x] = dst[(CLIP_Y + y) * dst_w + CLIP_X + x];
   645	        }
   646	    }
   647	
   648	  for (y = 0; y < dst_h; y++)
   649	    {
   650	      for (x = 0; x < dst_w; x++)
   651	        {
   652	          dst[y * dst_w + x] = SENTINEL;
   653	        }
   654	    }
   655	
   656	  if (!myvendor_epic_rotate_impl(src, (uint32_t)src_w * sizeof(uint16_t),
   657	          src_w, src_h, dst, (uint32_t)dst_w * sizeof(uint16_t), dst_w, dst_h,
   658	          angle10, piv, piv, dst_w / 2, dst_h / 2, CLIP_X, CLIP_Y, CLIP_W,
   659	          CLIP_H))
   660	    {
   661	      syslog(LOG_WARNING, "[vrot] area selftest SKIP: rotate_area failed");
   662	      return false;
   663	    }
   664	
   665	  for (y = 0; y < dst_h; y++)
   666	    {
   667	      for (x = 0; x < dst_w; x++)
   668	        {
   669	          const bool in = (x >= CLIP_X && x < CLIP_X + CLIP_W
   670	            && y >= CLIP_Y && y < CLIP_Y + CLIP_H);
   671	          const uint16_t got = dst[y * dst_w + x];
   672	
   673	          if (in)
   674	            {
   675	              if (got != snap[(y - CLIP_Y) * CLIP_W + (x - CLIP_X)])
   676	                {
   677	                  bad_in++;
   678	                }
   679	            }
   680	          else if (got != SENTINEL)
   681	            {
   682	              bad_out++;
   683	            }
   684	        }
   685	    }
   686	
   687	  syslog((bad_in == 0 && bad_out == 0) ? LOG_NOTICE : LOG_WARNING,
   688	    "[vrot] area selftest %s: in=%d out=%d (clip %d,%d %dx%d)",
   689	    (bad_in == 0 && bad_out == 0) ? "PASS" : "FAIL", (int)bad_in,
   690	    (int)bad_out, CLIP_X, CLIP_Y, CLIP_W, CLIP_H);
   770	
   771	    view->disp_arrow_angle10 = v;
   772	    lv_img_set_angle(view->arrow, v);
   773	}
