   775	/**
   776	 * @brief 把箭头角度从当前显示值补间到目标角（0.1°）。
   777	 * @param view       视图。
   778	 * @param angle10    目标角，0..3599。
   779	 * @param allow_anim false 时立即到位（首帧 / 隐藏后重新出现 / 正好掉头）。
   780	 */
   781	static void vmap_arrow_apply(vmap_view_t * view, int32_t angle10, bool allow_anim)
   782	{
   783	    int32_t cur;
   784	    int32_t delta;
   785	    lv_anim_t a;
   786	
   787	    if (view == NULL || view->arrow == NULL) {
   788	        return;
   789	    }
   790	
   791	    cur = view->disp_arrow_angle10;
   792	    if (cur == INT32_MIN || !allow_anim) {
   793	        lv_anim_delete(view, vmap_arrow_angle_exec);
   794	        view->disp_arrow_angle10 = angle10;
   795	        lv_img_set_angle(view->arrow, angle10);
   796	        return;
   797	    }
   798	
   799	    /* 最短弧：结果 -1800..1799（同模空间，cur 未归一化也成立）。 */
   800	    delta = ((angle10 - cur + 3600 + 1800) % 3600) - 1800;
   801	    if (abs(delta) < 30 || abs(delta) >= 1800) {
   802	        lv_anim_delete(view, vmap_arrow_angle_exec);
   803	        view->disp_arrow_angle10 = angle10;
   804	        lv_img_set_angle(view->arrow, angle10);
   805	        return;
   806	    }
   807	
   808	    lv_anim_delete(view, vmap_arrow_angle_exec);
   809	    lv_anim_init(&a);
   810	    lv_anim_set_var(&a, view);
   811	    lv_anim_set_values(&a, cur, cur + delta);
   812	    lv_anim_set_duration(&a, 180);
   813	    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
   814	    lv_anim_set_exec_cb(&a, vmap_arrow_angle_exec);
   815	    lv_anim_start(&a);
   816	}
