   818	static void tile_range(int32_t center_x, int32_t center_y, int32_t canvas_w,
   819	    int32_t canvas_h, double scale, int32_t ring,
   820	    int32_t * tx_min, int32_t * ty_min, int32_t * tx_max, int32_t * ty_max)
   821	{
   822	    const int32_t tile_size = 256;
   823	    double half_w = (canvas_w / 2.0) / scale;
   824	    double half_h = (canvas_h / 2.0) / scale;
   825	    double pad = (double)ring * tile_size;
   826	    double left = (double)center_x - half_w - pad;
   827	    double top = (double)center_y - half_h - pad;
   828	    double right = (double)center_x + half_w + pad;
   829	    double bottom = (double)center_y + half_h + pad;
   830	
   831	    *tx_min = (int32_t)(left / tile_size) - (left < 0 ? 1 : 0);
   832	    *ty_min = (int32_t)(top / tile_size) - (top < 0 ? 1 : 0);
   833	    *tx_max = (int32_t)(right / tile_size);
   834	    *ty_max = (int32_t)(bottom / tile_size);
   835	}
