  1063	/**
  1064	 * @brief 只把画布 C 的脏区按 r_rot10 重转进 R（角度没变时的增量路径）。
  1065	 *
  1066	 * @details 变换与 `vmap_rot_labels_update()` 逐式相同：R 中心 = (rw/2, rh/2)，
  1067	 *          pivot 落在 R 中心，角度 = r_rot10（0.1°，顺时针）。把 rot_dirty 四角
  1068	 *          投到 R 坐标取 AABB，外扩 2 px（最近邻取整的余量）后作为 clip。
  1069	 *
  1070	 *          pivot 与角度都取**上一次整幅烘焙时**的基准（r_pan_* / r_rot10），
  1071	 *          不是当前 pan/rot10：R 的对象之后可能被 `vmap_rot_track()` 平移过
  1072	 *          （buffer 内容不动、只有对象在挪），往 buffer 写像素必须和 R 其余像素
  1073	 *          同处"烘焙时"的坐标系；用当前 pan 会把补丁按对象位移错开（可达
  1074	 *          r_margin 级），源采样也会跟着错位。
  1075	 *
  1076	 * @return true = R 已跟上脏区（脏区整个投到 R 外也算，R 无需更新）；
  1077	 *         false = 参数/原语失败，调用方应回退整幅 `vmap_rot_full()`。
  1078	 */
  1079	static bool vmap_rot_area(vmap_view_t * view)
  1080	{
  1081	    int32_t pivot_x;
  1082	    int32_t pivot_y;
  1083	    int32_t cx[4];
  1084	    int32_t cy[4];
  1085	    int32_t x1;
  1086	    int32_t y1;
  1087	    int32_t x2;
  1088	    int32_t y2;
  1089	    int32_t i;
  1090	    uint32_t t0;
  1091	    uint32_t ms;
  1092	    double th;
  1093	    double c;
  1094	    double s;
  1095	    bool ok;
  1096	
  1097	    if (view == NULL || view->rbuf == NULL || view->cbuf == NULL
  1098	        || view->rcanvas == NULL || vmap_rot_dirty_empty(view)) {
  1099	        return false;
  1100	    }
  1101	
  1102	    /* pivot 与 vmap_rot_full 同算法，只是用烘焙时记下的 pan。 */
  1103	    pivot_x = view->margin + view->view_w / 2 + (int32_t)lround(view->r_pan_x);
  1104	    pivot_y = view->margin + view->view_h / 2 + (int32_t)lround(view->r_pan_y);
  1105	    if (pivot_x < 0 || pivot_y < 0 || pivot_x >= view->w || pivot_y >= view->h) {
  1106	        /* 烘焙时走的是"越界回退到画布中心"分支：这里复现不了，整幅更稳。 */
  1107	        return false;
  1108	    }
  1109	
  1110	    th = (double)view->r_rot10 * 0.1 * M_PI / 180.0;
  1111	    c = cos(th);
  1112	    s = sin(th);
  1113	
  1114	    cx[0] = view->rot_dirty_x0;
